"use client";

import Link from "next/link";
import { Save } from "lucide-react";
import { useRef, useState } from "react";
import type { AdminWorkflowColumn, AdminWorkflowMatrixRow } from "@/lib/types";

type AdminWorkflowTableProps = {
  columns: AdminWorkflowColumn[];
  initialRows: AdminWorkflowMatrixRow[];
};

export function AdminWorkflowTable({ columns, initialRows }: AdminWorkflowTableProps) {
  const [rows, setRows] = useState(initialRows);
  const [message, setMessage] = useState("");
  const [savingAll, setSavingAll] = useState(false);
  const [dirtyIds, setDirtyIds] = useState<number[]>([]);
  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});

  function markDirty(requestId: number) {
    setDirtyIds((current) => (current.includes(requestId) ? current : [...current, requestId]));
  }

  function updateCell(rowIndex: number, columnKey: string, value: string) {
    setRows((current) =>
      current.map((item, index) =>
        index === rowIndex
          ? {
              ...item,
              values: { ...item.values, [columnKey]: value },
            }
          : item,
      ),
    );
    markDirty(rows[rowIndex].requestId);
  }

  function focusCell(rowIndex: number, columnIndex: number) {
    cellRefs.current[`${rowIndex}:${columnIndex}`]?.focus();
  }

  function handlePaste(
    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
    rowIndex: number,
    columnIndex: number,
  ) {
    const text = event.clipboardData.getData("text");
    if (!text.includes("\t") && !text.includes("\n")) return;

    event.preventDefault();
    const matrix = text
      .replace(/\r/g, "")
      .split("\n")
      .filter((line) => line.length > 0)
      .map((line) => line.split("\t"));

    setRows((current) =>
      current.map((row, currentRowIndex) => {
        const pastedRow = matrix[currentRowIndex - rowIndex];
        if (!pastedRow) return row;

        const values = { ...row.values };
        pastedRow.forEach((cellValue, offset) => {
          const column = columns[columnIndex + offset];
          if (!column) return;
          values[column.key] = cellValue;
        });

        return { ...row, values };
      }),
    );

    const touchedIds = matrix
      .map((_, offset) => rows[rowIndex + offset]?.requestId)
      .filter((value): value is number => Boolean(value));
    setDirtyIds((current) => [...new Set([...current, ...touchedIds])]);
  }

  function handleKeyDown(
    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
    rowIndex: number,
    columnIndex: number,
  ) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      focusCell(rowIndex, Math.min(columnIndex + 1, columns.length - 1));
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      focusCell(rowIndex, Math.max(columnIndex - 1, 0));
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      focusCell(Math.min(rowIndex + 1, rows.length - 1), columnIndex);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      focusCell(Math.max(rowIndex - 1, 0), columnIndex);
    } else if (event.key === "Tab" && !event.shiftKey) {
      event.preventDefault();
      const nextColumnIndex = columnIndex + 1;
      if (nextColumnIndex < columns.length) {
        focusCell(rowIndex, nextColumnIndex);
      } else if (rowIndex < rows.length - 1) {
        focusCell(rowIndex + 1, 0);
      }
    } else if (event.key === "Tab" && event.shiftKey) {
      event.preventDefault();
      const prevColumnIndex = columnIndex - 1;
      if (prevColumnIndex >= 0) {
        focusCell(rowIndex, prevColumnIndex);
      } else if (rowIndex > 0) {
        focusCell(rowIndex - 1, columns.length - 1);
      }
    }
  }

  async function handleSaveRow(rowIndex: number) {
    const row = rows[rowIndex];
    const response = await fetch("/api/admin/workflow", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        requestId: row.requestId,
        values: row.values,
      }),
    });
    const data = (await response.json().catch(() => ({}))) as { message?: string };
    setMessage(response.ok ? "전형단계별 학과 입력시트를 저장했습니다." : data.message ?? "저장에 실패했습니다.");
    if (response.ok) {
      setDirtyIds((current) => current.filter((id) => id !== row.requestId));
    }
  }

  async function handleSaveAll() {
    if (!dirtyIds.length) {
      setMessage("저장할 변경 사항이 없습니다.");
      return;
    }

    setSavingAll(true);
    for (const requestId of dirtyIds) {
      const rowIndex = rows.findIndex((row) => row.requestId === requestId);
      if (rowIndex !== -1) {
        await handleSaveRow(rowIndex);
      }
    }
    setSavingAll(false);
    setMessage("변경한 항목을 모두 저장했습니다.");
  }

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <button
          type="button"
          onClick={handleSaveAll}
          disabled={savingAll}
          className="inline-flex items-center gap-2 rounded-[10px] border border-[#6a7f48] bg-[#394727] px-4 py-2 text-sm text-[#f3f1d4] disabled:opacity-60"
        >
          <Save className="h-4 w-4" />
          {savingAll ? "일괄 저장 중..." : `변경행 일괄 저장 (${dirtyIds.length})`}
        </button>
        <p className="text-sm text-[#6b7280]">
          엑셀이나 구글시트에서 복사해 붙여넣으면 여러 단계 입력칸을 한 번에 채울 수 있습니다.
        </p>
      </div>

      {message ? <p className="mb-4 rounded-[10px] bg-[#f0f9f4] px-4 py-3 text-sm text-[#374151]">{message}</p> : null}

      <div className="max-h-[72vh] overflow-auto">
        <table className="min-w-[2400px] border-separate border-spacing-0 text-sm">
          <thead>
            <tr>
              {["소속대학", "학과명", "(최종) 초빙분야", "채용구분", "현재단계"].map((label, index) => (
                <th
                  key={label}
                  className="sticky top-0 z-30 border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                  style={{ minWidth: index < 3 ? 220 : 160 }}
                >
                  {label}
                </th>
              ))}
              {columns.map((column) => (
                <th
                  key={column.key}
                  className="sticky top-0 z-20 border-b border-r border-[#e5e7eb] bg-[#f3f4f6] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                  style={{ minWidth: 220 }}
                >
                  <span className="block text-xs text-[#6b7280]">{column.stepKey}</span>
                  <span className="mt-1 block whitespace-pre-wrap">{column.label}</span>
                </th>
              ))}
              <th className="sticky top-0 z-20 border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]">
                작업
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIndex) => (
              <tr key={row.requestId} className={rowIndex % 2 === 0 ? "bg-white" : "bg-[#f9fafb]"}>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.college}</td>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.deptName}</td>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 font-semibold text-[#111827]">{row.fieldName}</td>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">{row.hiringType}</td>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">{row.currentStatus}</td>
                {columns.map((column, columnIndex) => (
                  <td key={`${row.requestId}-${column.key}`} className="border-b border-r border-[#f0f0f0] px-3 py-3 align-top">
                    {column.inputType === "textarea" ? (
                      <textarea
                        ref={(node) => {
                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
                        }}
                        rows={4}
                        value={row.values[column.key] ?? ""}
                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs leading-6 text-[#111827] outline-none focus:border-[#7fb18f]"
                      />
                    ) : (
                      <input
                        ref={(node) => {
                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
                        }}
                        type={column.inputType === "date" ? "text" : column.inputType}
                        value={row.values[column.key] ?? ""}
                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
                        placeholder={column.inputType === "date" ? "YYYY-MM-DD" : ""}
                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs text-[#111827] outline-none focus:border-[#7fb18f]"
                      />
                    )}
                  </td>
                ))}
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">
                  <div className="flex min-w-[180px] flex-col items-center gap-2">
                    <button
                      type="button"
                      onClick={() => handleSaveRow(rowIndex)}
                      className="rounded-[10px] bg-[#1f5b43] px-4 py-2 text-xs font-semibold text-white"
                    >
                      저장
                    </button>
                    <Link
                      href={`/procedures/${row.requestId}`}
                      className="rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-xs font-semibold text-[#374151]"
                    >
                      절차 상세
                    </Link>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { Download, Save, Upload } from "lucide-react";
import type { AdminRequestSheetRow } from "@/lib/types";

type AdminRequestSheetProps = {
  initialRows: AdminRequestSheetRow[];
};

const EDITABLE_COLUMNS: Array<{
  key: keyof Omit<AdminRequestSheetRow, "requestId" | "college" | "deptName">;
  label: string;
  multiline?: boolean;
}> = [
  { key: "fieldName", label: "(최종) 초빙분야" },
  { key: "hiringType", label: "채용구분" },
  { key: "priority", label: "우선순위" },
  { key: "requestedCount", label: "요청 인원" },
  { key: "allocationResult", label: "배정 인원" },
  { key: "status", label: "현재 단계" },
  { key: "nextAction", label: "현재 필요 조치", multiline: true },
  { key: "requestedGeneral", label: "요청 일반" },
  { key: "requestedDedicated", label: "요청 전담" },
  { key: "requestedForeign", label: "요청 외" },
  { key: "kriFieldName", label: "KRI 분야", multiline: true },
  { key: "hiringReason", label: "채용 사유", multiline: true },
  { key: "deptRequestReason", label: "학과 요청 사유", multiline: true },
  { key: "subjectAssignment", label: "과목 배정", multiline: true },
  { key: "meetingNotes", label: "회의 메모", multiline: true },
  { key: "notes", label: "비고", multiline: true },
];

function buildPayload(row: AdminRequestSheetRow) {
  return {
    fieldName: row.fieldName,
    hiringType: row.hiringType,
    priority: row.priority,
    requestedCount: row.requestedCount,
    allocationResult: row.allocationResult,
    status: row.status,
    nextAction: row.nextAction,
    requestedGeneral: row.requestedGeneral,
    requestedDedicated: row.requestedDedicated,
    requestedForeign: row.requestedForeign,
    kriFieldName: row.kriFieldName,
    hiringReason: row.hiringReason,
    deptRequestReason: row.deptRequestReason,
    subjectAssignment: row.subjectAssignment,
    meetingNotes: row.meetingNotes,
    notes: row.notes,
  };
}

export function AdminRequestSheet({ initialRows }: AdminRequestSheetProps) {
  const [rows, setRows] = useState(initialRows);
  const [message, setMessage] = useState("");
  const [uploading, setUploading] = useState(false);
  const [savingAll, setSavingAll] = useState(false);
  const [dirtyIds, setDirtyIds] = useState<number[]>([]);
  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});

  function markDirty(requestId: number) {
    setDirtyIds((current) => (current.includes(requestId) ? current : [...current, requestId]));
  }

  function updateCell(rowIndex: number, columnKey: (typeof EDITABLE_COLUMNS)[number]["key"], value: string) {
    setRows((current) =>
      current.map((item, index) => (index === rowIndex ? { ...item, [columnKey]: value } : item)),
    );
    markDirty(rows[rowIndex].requestId);
  }

  function focusCell(rowIndex: number, columnIndex: number) {
    const key = `${rowIndex}:${columnIndex}`;
    cellRefs.current[key]?.focus();
  }

  function handlePaste(
    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
    rowIndex: number,
    columnIndex: number,
  ) {
    const text = event.clipboardData.getData("text");
    if (!text.includes("\t") && !text.includes("\n")) return;

    event.preventDefault();
    const matrix = text
      .replace(/\r/g, "")
      .split("\n")
      .filter((line) => line.length > 0)
      .map((line) => line.split("\t"));

    setRows((current) =>
      current.map((row, currentRowIndex) => {
        const pastedRow = matrix[currentRowIndex - rowIndex];
        if (!pastedRow) return row;

        const nextRow = { ...row };
        pastedRow.forEach((cellValue, offset) => {
          const column = EDITABLE_COLUMNS[columnIndex + offset];
          if (!column) return;
          nextRow[column.key] = cellValue;
        });
        return nextRow;
      }),
    );

    const touchedIds = matrix
      .map((_, offset) => rows[rowIndex + offset]?.requestId)
      .filter((value): value is number => Boolean(value));
    setDirtyIds((current) => [...new Set([...current, ...touchedIds])]);
  }

  function handleKeyDown(
    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
    rowIndex: number,
    columnIndex: number,
  ) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      focusCell(rowIndex, Math.min(columnIndex + 1, EDITABLE_COLUMNS.length - 1));
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      focusCell(rowIndex, Math.max(columnIndex - 1, 0));
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      focusCell(Math.min(rowIndex + 1, rows.length - 1), columnIndex);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      focusCell(Math.max(rowIndex - 1, 0), columnIndex);
    } else if (event.key === "Tab" && !event.shiftKey) {
      event.preventDefault();
      const nextColumnIndex = columnIndex + 1;
      if (nextColumnIndex < EDITABLE_COLUMNS.length) {
        focusCell(rowIndex, nextColumnIndex);
      } else if (rowIndex < rows.length - 1) {
        focusCell(rowIndex + 1, 0);
      }
    } else if (event.key === "Tab" && event.shiftKey) {
      event.preventDefault();
      const prevColumnIndex = columnIndex - 1;
      if (prevColumnIndex >= 0) {
        focusCell(rowIndex, prevColumnIndex);
      } else if (rowIndex > 0) {
        focusCell(rowIndex - 1, EDITABLE_COLUMNS.length - 1);
      }
    }
  }

  async function handleSaveRow(rowIndex: number) {
    const row = rows[rowIndex];
    const response = await fetch("/api/admin/request-sheet", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ requestId: row.requestId, values: buildPayload(row) }),
    });
    const data = (await response.json().catch(() => ({}))) as { message?: string };
    setMessage(response.ok ? "DB 연동 편집 시트를 저장했습니다." : data.message ?? "저장에 실패했습니다.");
    if (response.ok) {
      setDirtyIds((current) => current.filter((id) => id !== row.requestId));
    }
  }

  async function handleSaveAll() {
    if (!dirtyIds.length) {
      setMessage("저장할 변경 사항이 없습니다.");
      return;
    }

    setSavingAll(true);
    for (const requestId of dirtyIds) {
      const rowIndex = rows.findIndex((row) => row.requestId === requestId);
      if (rowIndex !== -1) {
        await handleSaveRow(rowIndex);
      }
    }
    setSavingAll(false);
    setMessage("변경한 항목을 모두 저장했습니다.");
  }

  async function handleImport(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;

    setUploading(true);
    const formData = new FormData();
    formData.set("file", file);

    const response = await fetch("/api/admin/request-sheet/import", {
      method: "POST",
      body: formData,
    });
    const data = (await response.json().catch(() => ({}))) as { message?: string; count?: number };
    if (response.ok) {
      setMessage(`엑셀 업로드를 반영했습니다. ${data.count ?? 0}개 항목을 갱신했습니다.`);
      window.location.reload();
      return;
    }

    setMessage(data.message ?? "엑셀 업로드에 실패했습니다.");
    setUploading(false);
  }

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={() => window.location.assign("/api/admin/request-sheet/export")}
            className="inline-flex items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-sm text-[#374151]"
          >
            <Download className="h-4 w-4" />
            엑셀 다운로드
          </button>
          <label className="inline-flex cursor-pointer items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-[#f9fafb] px-4 py-2 text-sm text-[#374151]">
            <Upload className="h-4 w-4" />
            {uploading ? "업로드 중..." : "엑셀 업로드"}
            <input type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={handleImport} />
          </label>
          <button
            type="button"
            onClick={handleSaveAll}
            disabled={savingAll}
            className="inline-flex items-center gap-2 rounded-[10px] border border-[#6a7f48] bg-[#394727] px-4 py-2 text-sm text-[#f3f1d4] disabled:opacity-60"
          >
            <Save className="h-4 w-4" />
            {savingAll ? "일괄 저장 중..." : `변경행 일괄 저장 (${dirtyIds.length})`}
          </button>
        </div>
        <p className="text-sm text-[#6b7280]">
          엑셀이나 구글시트에서 범위를 복사해 붙여넣으면 여러 칸을 한 번에 반영할 수 있습니다.
        </p>
      </div>

      {message ? <p className="mb-4 rounded-[10px] bg-[#f0f9f4] px-4 py-3 text-sm text-[#374151]">{message}</p> : null}

      <div className="max-h-[72vh] overflow-auto">
        <table className="min-w-[2800px] border-separate border-spacing-0 text-sm">
          <thead>
            <tr>
              {["소속대학", "학과명", ...EDITABLE_COLUMNS.map((column) => column.label), "저장"].map((label) => (
                <th
                  key={label}
                  className="sticky top-0 z-20 border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                  style={{ minWidth: label === "저장" ? 140 : 220 }}
                >
                  {label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIndex) => (
              <tr key={row.requestId} className={rowIndex % 2 === 0 ? "bg-white" : "bg-[#f9fafb]"}>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.college}</td>
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.deptName}</td>
                {EDITABLE_COLUMNS.map((column, columnIndex) => (
                  <td key={`${row.requestId}-${column.key}`} className="border-b border-r border-[#f0f0f0] px-3 py-3 align-top">
                    {column.multiline ? (
                      <textarea
                        ref={(node) => {
                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
                        }}
                        rows={4}
                        value={String(row[column.key] ?? "")}
                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs leading-6 text-[#111827] outline-none focus:border-[#7fb18f]"
                      />
                    ) : (
                      <input
                        ref={(node) => {
                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
                        }}
                        type="text"
                        value={String(row[column.key] ?? "")}
                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs text-[#111827] outline-none focus:border-[#7fb18f]"
                      />
                    )}
                  </td>
                ))}
                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">
                  <button
                    type="button"
                    onClick={() => handleSaveRow(rowIndex)}
                    className="rounded-[10px] bg-[#1f5b43] px-4 py-2 text-xs font-semibold text-white"
                  >
                    저장
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
